<br />code
<br />C#
<br />using StardewModdingAPI;
<br />using StardewModdingAPI.Events;
<br />using StardewValley;
<br />using StardewValley.Buildings;
<br />namespace AutoFillPetBowl;
<br />public class ModEntry : Mod
<br />{
<br />    // The 'null!' tells the compiler "trust me, this won't be null when I use it"
<br />    private ModConfig Config = null!;
<br />    public override void Entry(IModHelper helper)
<br />    {
<br />        this.Config = helper.ReadConfig&lt;ModConfig&gt;();
<br />        helper.Events.GameLoop.DayStarted += this.OnDayStarted;
<br />    }
